const body = $input.first().json.body || $input.first().json;
const cargos = body.cargos || [];
const masters = body.masters || [];
const uploadId = body.upload_id;
const backendUrl = body.backend_url || 'https://shr-backend-prod.onrender.com';

if (cargos.length === 0) return [];

const mastersText = masters.slice(0, 40).map(m => `- ${m.nombre}: ${(m.descripcion || '').substring(0, 100)}`).join('\n');
const cargosText = cargos.map((c, i) => `${i+1}. ${c.nombre} (${c.area || 'N/A'})`).join('\n');

return [{
  json: {
    upload_id: uploadId,
    backend_url: backendUrl,
    masters_text: mastersText,
    prompt: `Eres experto RRHH Colombia. HOMOLOGAR:\n${cargosText}\n\nMAESTROS:\n${mastersText}\n\nResponde JSON array: [{"cargo_id":ID,"cargo_homologado":"NOMBRE","justificacion":"razon","status":"homologado"}]`
  }
}];

const items = [];
for (const item of $input.all()) {
  try {
    const content = (item.json.choices?.[0]?.message?.content || '').replace(/```json/g, '').replace(/```/g, '').trim();
    let results = [];
    try { results = JSON.parse(content); } catch(e) {
      const match = content.match(/\[[\s\S]*\]/);
      if (match) results = JSON.parse(match[0]);
    }
    if (!Array.isArray(results)) results = [results];
    const orig = item.json;
    for (const r of results) {
      items.push({ json: { cargo_id: r.cargo_id || orig.cargo_id || 0, cargo_homologado: r.cargo_homologado || 'SIN COINCIDENCIA', justificacion: r.justificacion || '', status: r.status || 'sin_coincidencia', upload_id: orig.upload_id, backend_url: orig.backend_url } });
    }
  } catch(e) {
    items.push({ json: { cargo_id: 0, cargo_homologado: 'SIN COINCIDENCIA', justificacion: 'Error: ' + e.message, status: 'error', upload_id: 0, backend_url: '' } });
  }
}
return items;
